export const SITE_URL = "https://www.tinybundle.app";

export const ogImageSize = {
  width: 1200,
  height: 630,
} as const;

/** File-based OG routes generated by Next.js (`opengraph-image.tsx`). */
export function routeOgImage(path: string, alt: string) {
  const base = path === "/" ? "" : path.replace(/\/$/, "");
  return {
    url: `${base}/opengraph-image`,
    width: ogImageSize.width,
    height: ogImageSize.height,
    alt,
  } as const;
}

export const bundleOgImage = routeOgImage(
  "/",
  "TinyBundle: four little apps, one job each. Calm parenting apps for baby sleep, first foods, play and daily care.",
);

export const layersOgImage = routeOgImage(
  "/tinylayers",
  "TinyLayers: too warm or too cold? What your baby should wear for tonight’s room.",
);

export const bloomsOgImage = routeOgImage(
  "/tinyblooms",
  "TinyBlooms: baby activities, milestones and memories, ages 0 to 5.",
);

export const napsOgImage = routeOgImage(
  "/tinynaps",
  "TinyNaps: baby sleep, feeding and diaper tracker for iPhone.",
);

export const mealsOgImage = routeOgImage(
  "/tinymeals",
  "TinyMeals - Today’s meal, worked out for you. One gentle recipe a day for your baby’s age and stage.",
);

export function absoluteUrl(path: string) {
  if (path.startsWith("http")) return path;
  return `${SITE_URL}${path.startsWith("/") ? path : `/${path}`}`;
}
